*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:#fbf7f0;color:#34312d;font:16px/1.65 Arial,Helvetica,sans-serif}a{color:inherit;text-underline-offset:5px}button,input{font:inherit}button,a,input{touch-action:manipulation}button:focus-visible,a:focus-visible,input:focus-visible{outline:3px solid #8c5b2e;outline-offset:5px}.shell{max-width:1220px;margin:auto;padding:0 5%}.nav{display:flex;justify-content:space-between;align-items:center;gap:22px;padding:27px 0;border-bottom:1px solid #d9d1c5}.wordmark{font:normal 29px Georgia,serif;text-decoration:none}.navlinks{display:flex;gap:30px;font-size:12px}.navlinks a{text-decoration:none}.hero{display:grid;grid-template-columns:1.1fr 1fr;gap:50px;align-items:center;padding:65px 0 75px}.eyebrow{color:#755143;font-size:10px;letter-spacing:2.4px;text-transform:uppercase;font-weight:700}.hero h1{font:normal clamp(42px,4.8vw,65px)/1.08 Georgia,serif;letter-spacing:-2px;margin:21px 0 27px}.hero h1 em{color:#6b3543;font-weight:normal}.lead{color:#635d55;max-width:435px;margin-bottom:28px}.btn{display:inline-flex;justify-content:center;align-items:center;gap:16px;background:#61333e;color:#fff;padding:13px 22px;border:1px solid #61333e;text-decoration:none;font-size:12px;cursor:pointer}.btn.light{color:#61333e;background:transparent}.smalllink{font-size:12px;margin-left:20px}.scene{height:430px;position:relative;display:flex;justify-content:center;align-items:center;background:radial-gradient(ellipse at 50% 82%,#d9ccbb 0,transparent 60%);border-radius:50% 50% 0 0}.scene:after{content:'';position:absolute;bottom:11px;left:8%;right:8%;height:13px;border-radius:50%;background:#c5b6a2;filter:blur(11px);z-index:0}.book{width:245px;height:356px;background:#284545;color:#f6ead4;box-shadow:11px 15px 25px #3b342e2e,4px 0 0 #e6decc;border-left:9px solid #203c3b;position:relative;padding:24px;display:flex;flex-direction:column;z-index:1;transform:rotate(-5deg)}.book:before{content:'';position:absolute;left:35px;right:25px;top:66px;height:174px;border:1px solid #d6ba90;transform:rotate(25deg);border-radius:50% 50% 0 50%}.book:after{content:'';position:absolute;left:45px;right:38px;top:91px;height:161px;border:1px solid #819e94;transform:rotate(-24deg);border-radius:50%}.book .author{font-size:9px;letter-spacing:3px;text-align:center;z-index:1}.book .booktitle{font:normal 48px/1.05 Georgia,serif;letter-spacing:-1px;margin:auto 0 10px;z-index:1}.book .genre{font-size:9px;letter-spacing:2px;z-index:1}.scene-note{position:absolute;bottom:14px;right:0;max-width:120px;font-size:10px;color:#6d5e4e;line-height:1.6;letter-spacing:1px}.sectionhead{display:flex;align-items:baseline;justify-content:space-between;gap:20px;padding-top:32px;border-top:1px solid #b8ab9b}.sectionhead h2{font:normal 35px Georgia,serif;margin:0}.sectionhead span{font-size:11px;color:#755143}.books{display:grid;grid-template-columns:1fr 1fr;gap:30px;margin:28px 0 65px}.bookcard{display:grid;grid-template-columns:128px 1fr;gap:25px;align-items:center;border:1px solid #d9d1c5;padding:27px}.mini{width:125px;height:180px;transform:none;padding:13px;border-left-width:5px;box-shadow:5px 5px 12px #3b342e22}.mini:before{top:37px;height:76px;left:22px;right:12px}.mini:after{top:52px;height:82px;left:19px;right:16px}.mini .author{font-size:6px;letter-spacing:1.4px}.mini .booktitle{font-size:26px}.mini .genre{font-size:6px}.rose{background:#714450;border-left-color:#58333f}.bookcard h3{font:normal 23px Georgia,serif;margin:7px 0 10px}.bookcard p{font-size:13px;color:#635d55;margin:0 0 16px}.textbutton{border:0;border-bottom:1px solid #61333e;background:none;color:#61333e;padding:3px 0;font-size:12px;cursor:pointer}.about{display:grid;grid-template-columns:1fr 1.5fr;gap:60px;padding:47px 0;border-top:1px solid #b8ab9b}.about h2{font:normal 40px/1.15 Georgia,serif;margin:10px 0}.about p{font:18px/1.8 Georgia,serif;margin:5px 0 16px;color:#635d55}.letters{background:#e9e0d3;padding:40px;margin:20px 0 55px;display:grid;grid-template-columns:1fr 1fr;gap:40px;align-items:center}.letters h2{font:normal 34px/1.15 Georgia,serif;margin:10px 0 15px}.letters p{font-size:13px;max-width:390px;color:#635d55}.letters label{font-size:11px;display:block;margin-bottom:8px}.signup{display:flex;gap:9px}.signup input{min-width:0;width:100%;padding:12px;border:1px solid #9b8d7b;background:#fbf7f0;color:#34312d;border-radius:0;font-size:13px}.signup .btn{white-space:nowrap;padding:12px 18px}.privacy{font-size:10px!important;margin:10px 0 0}.result{font-size:12px!important;color:#344b3e!important}.footer{display:flex;justify-content:space-between;gap:20px;padding:23px 0;border-top:1px solid #d9d1c5;font-size:10px;color:#6d6459}dialog{border:1px solid #d9d1c5;background:#fbf7f0;color:#34312d;width:min(690px,calc(100% - 32px));max-height:85vh;padding:35px 42px}dialog::backdrop{background:#28232099}.dialogtop{display:flex;justify-content:space-between;gap:15px;align-items:center}.close{background:transparent;border:1px solid #9b8d7b;padding:6px 12px;cursor:pointer;font-size:12px}dialog h2{font:normal 39px/1.1 Georgia,serif}dialog .excerpt{font:18px/1.85 Georgia,serif}.wp-site-blocks{padding:0!important}.wp-block-post-content{margin:0!important}@media(max-width:900px){.hero{gap:20px}.books{grid-template-columns:1fr}.bookcard{grid-template-columns:125px 1fr}.letters{gap:25px;padding:28px}.signup{flex-direction:column}}@media(max-width:620px){.nav{padding:21px 0;gap:10px}.wordmark{font-size:24px}.navlinks{gap:18px;font-size:11px}.navlinks .aboutlink{display:none}.hero{grid-template-columns:1fr;padding:36px 0 45px;gap:12px}.hero h1{font-size:43px;letter-spacing:-1.3px}.hero .lead{font-size:15px}.scene{height:333px}.scene>.book{width:194px;height:280px;padding:19px}.scene .booktitle{font-size:39px}.scene>.book:before{top:50px;height:132px}.scene>.book:after{top:64px;height:127px}.scene-note{font-size:9px;max-width:87px}.sectionhead h2{font-size:30px}.bookcard{padding:20px;gap:21px;grid-template-columns:102px 1fr}.mini{width:98px;height:151px;padding:10px}.mini .booktitle{font-size:22px}.books{margin-bottom:42px;gap:18px}.about{grid-template-columns:1fr;gap:8px;padding:32px 0}.about h2{font-size:33px}.letters{grid-template-columns:1fr;gap:16px;padding:25px;margin-bottom:32px}.signup{flex-direction:row}.signup .btn{font-size:11px;padding:12px}.footer{flex-wrap:wrap}.smalllink{margin-left:15px}dialog{padding:24px}dialog h2{font-size:32px}}.samplebar{padding:8px 5%;background:#e6eade;color:#475b46;display:flex;justify-content:space-between;gap:15px;font:11px Arial}.samplebar a{font-weight:bold;text-decoration:underline;color:inherit}@media(max-width:650px){.samplebar{font-size:9px}}
.wp-site-blocks{padding:0!important}.wp-block-post-content{margin:0!important}
